"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { LucideIcon } from "lucide-react";
import {
  Activity, ArrowDownRight, ArrowRight, ArrowUpRight, Bell, BookOpen, Bot, Building2, Check, ChevronDown,
  ChevronRight, CircleHelp, Clock3, Code2, Copy, ExternalLink, FileCode2, Globe2, LayoutDashboard, MapPin,
  Menu, MessageCircle, MoreHorizontal, Phone, Plus, RefreshCw, Search, Settings2, Sparkles, Target,
  Trash2, TrendingUp, Users, X, Zap,
} from "lucide-react";
import {
  BUSINESS_TYPES, buildPageCopy, buildPageSchema, csvText, dateInZone, emptyLocalWorkspace, locationLabel,
  randomLocalId, safeSchemaJson, slugify, type LocalAction, type LocalBusiness, type LocalContentBlock,
  type LocalLead, type LocalLeadChannel, type LocalLocation, type LocalPage, type LocalPageStatus,
  type LocalService, type LocalWorkspace,
} from "@/lib/local-workspace";

type View = "Overview" | "Page engine" | "Leads" | "Business profile" | "Content library";
type Dialog = { kind: "setup" } | { kind: "lead"; lead?: LocalLead } | { kind: "block"; block?: LocalContentBlock } | null;
type Tone = "sky" | "violet" | "amber" | "teal" | "peach" | "mint";
type LocalPersistence = "loading" | "server" | "unavailable";

const navigation: { label: View; icon: LucideIcon }[] = [
  { label: "Overview", icon: LayoutDashboard }, { label: "Page engine", icon: Zap }, { label: "Leads", icon: Target },
  { label: "Business profile", icon: Building2 }, { label: "Content library", icon: BookOpen },
];
const pageCopy: Record<View, { eyebrow: string; title: string; description: string }> = {
  Overview: { eyebrow: "LOCAL GROWTH WORKSPACE", title: "Start with the places you serve.", description: "Set up your business once, then turn service and location combinations into reviewable landing pages." },
  "Page engine": { eyebrow: "PROGRAMMATIC LANDING PAGES", title: "Build your local footprint.", description: "Create service-and-location pages from your real business data. Nothing is published until you choose it." },
  Leads: { eyebrow: "LEAD PIPELINE", title: "Turn local intent into booked work.", description: "Review enquiries from your generated pages and keep every follow-up in one place." },
  "Business profile": { eyebrow: "BUSINESS PROFILE", title: "Give every page a source of truth.", description: "Your name, services, locations, contact details, and profile connection live here." },
  "Content library": { eyebrow: "LOCAL CONTENT SYSTEM", title: "Add proof that makes pages useful.", description: "Save testimonials, FAQs, and location context once. Reuse them across the pages you generate." },
};

async function requestLocal(action?: LocalAction): Promise<LocalWorkspace> {
  const response = await fetch("/api/local", { method: action ? "POST" : "GET", headers: action ? { "Content-Type": "application/json" } : undefined, body: action ? JSON.stringify(action) : undefined, cache: "no-store" });
  const data: unknown = await response.json();
  if (!response.ok) throw new Error(data && typeof data === "object" && "error" in data && typeof data.error === "string" ? data.error : "LocalPilot could not save that change.");
  return data as LocalWorkspace;
}
function textError(error: unknown): string { return error instanceof Error ? error.message : "Something went wrong. Try again."; }
function initials(value: string): string { return value.trim().split(/\s+/).map(part => part[0]).join("").slice(0, 2).toUpperCase() || "LP"; }
function colorFor(index: number): Tone { return (["sky", "violet", "amber", "teal"] as Tone[])[index % 4]; }
function relativeTime(value: string): string { const delta = Date.now() - Date.parse(value); if (!Number.isFinite(delta) || delta < 60_000) return "just now"; if (delta < 3_600_000) return `${Math.floor(delta / 60_000)}m ago`; if (delta < 86_400_000) return `${Math.floor(delta / 3_600_000)}h ago`; return `${Math.floor(delta / 86_400_000)}d ago`; }
function displayUpdated(value: string): string { try { return new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" }).format(new Date(value)); } catch { return "—"; } }
function pageLeadCount(workspace: LocalWorkspace, pageId: string): number { return workspace.leads.filter(lead => lead.pageId === pageId).length; }
function pageFor(workspace: LocalWorkspace, service: LocalService | undefined, location: LocalLocation | undefined, index = 0): LocalPage | null {
  if (!service || !location) return null;
  const copy = buildPageCopy(workspace.business, service, location);
  return { id: "preview", serviceId: service.id, locationId: location.id, slug: `${slugify(service.name)}-${slugify(locationLabel(location))}`, ...copy, status: "Draft", visits: 0, calls: 0, whatsappClicks: 0, formSubmissions: 0, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() };
}
function businessCompletion(business: LocalBusiness): number { const fields = [business.name, business.category !== "LocalBusiness" ? business.category : "", business.phone, business.website, business.description, business.gbpUrl]; return Math.round(fields.filter(Boolean).length / fields.length * 100); }
function downloadFile(name: string, content: string, type: string): void { const blob = new Blob([content], { type }); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = name; link.click(); URL.revokeObjectURL(url); }

function StatusPill({ status }: { status: LocalPageStatus | LocalLead["status"] }) {
  return <span className={`local-status ${status.toLowerCase().replaceAll(" ", "-")}`}><span className="local-status-dot" />{status}</span>;
}
function MetricCard({ label, value, change, detail, icon: Icon, tone, down = false }: { label: string; value: string; change?: string; detail: string; icon: LucideIcon; tone: Tone; down?: boolean }) {
  return <article className="local-metric-card"><div className="local-metric-head"><span className={`local-metric-icon ${tone}`}><Icon size={17} strokeWidth={2} /></span><span className="local-metric-label">{label}</span></div><div className="local-metric-value">{value}</div><div className="local-metric-foot">{change && <span className={`local-trend ${down ? "down" : ""}`}>{down ? <ArrowDownRight size={13} /> : <ArrowUpRight size={13} />}{change}</span>}<span>{detail}</span></div></article>;
}
function EmptyState({ title, description, action }: { title: string; description: string; action?: React.ReactNode }) {
  return <div className="local-empty-state"><span className="local-empty-icon"><Sparkles size={18} /></span><strong>{title}</strong><p>{description}</p>{action}</div>;
}
function ChannelIcon({ channel }: { channel: LocalLeadChannel }) {
  if (channel === "WhatsApp") return <span className="local-channel-icon whatsapp"><MessageCircle size={14} /></span>;
  if (channel === "Call") return <span className="local-channel-icon call"><Phone size={14} /></span>;
  return <span className="local-channel-icon form"><FileCode2 size={14} /></span>;
}
function CoverageChart({ workspace }: { workspace: LocalWorkspace }) {
  const rows = workspace.locations.map(location => ({ location, count: workspace.pages.filter(page => page.locationId === location.id).length }));
  const max = Math.max(...rows.map(row => row.count), 1);
  return <div className="coverage-chart">{rows.length === 0 || workspace.pages.length === 0 ? <EmptyState title="Your coverage chart starts here" description="Add a service and location, then generate your first local page." /> : rows.map((row, index) => <div className="coverage-row" key={row.location.id}><div><span>{locationLabel(row.location)}</span><strong>{row.count}</strong></div><div className="coverage-track"><span className={`coverage-fill ${colorFor(index)}`} style={{ width: `${Math.max(6, row.count / max * 100)}%` }} /></div></div>)}</div>;
}
function PageRow({ page, workspace, index, onPreview }: { page: LocalPage; workspace: LocalWorkspace; index: number; onPreview: (pageId: string) => void }) {
  return <button className="page-row" onClick={() => onPreview(page.id)}><span className={`page-row-icon ${colorFor(index)}`}><Globe2 size={16} /></span><span className="page-row-main"><strong>{page.title}</strong><small>/{page.slug}</small></span><span className="page-row-status"><StatusPill status={page.status} /></span><span className="page-row-ctr"><strong>{page.visits}</strong><small>views</small></span><span className="page-row-leads"><strong>{pageLeadCount(workspace, page.id)}</strong><small>leads</small></span><span className="page-row-updated">{relativeTime(page.updatedAt)}</span><ChevronRight size={16} className="page-row-arrow" /></button>;
}
function LeadRow({ lead, workspace, onSelect }: { lead: LocalLead; workspace?: LocalWorkspace; onSelect: (lead: LocalLead) => void }) {
  const page = workspace?.pages.find(item => item.id === lead.pageId);
  return <button className="lead-row" onClick={() => onSelect(lead)}><span className={`lead-avatar ${lead.channel === "WhatsApp" ? "mint" : lead.channel === "Call" ? "blue" : "lavender"}`}>{initials(lead.name)}</span><span className="lead-person"><strong>{lead.name}</strong><small>{page?.title || "Manual enquiry"}</small></span><span className="lead-channel"><ChannelIcon channel={lead.channel} />{lead.channel}</span><span className="lead-status"><StatusPill status={lead.status} /></span><span className="lead-value"><strong>{lead.value == null ? "—" : new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 }).format(lead.value)}</strong><small>{relativeTime(lead.createdAt)}</small></span><ChevronRight size={15} className="lead-row-arrow" /></button>;
}
function ModalShell({ title, eyebrow, description, onClose, children, className = "" }: { title: string; eyebrow: string; description: string; onClose: () => void; children: React.ReactNode; className?: string }) {
  return <div className="local-modal-layer" role="presentation" onMouseDown={event => { if (event.currentTarget === event.target) onClose(); }}><section className={`local-modal ${className}`} role="dialog" aria-modal="true"><div className="local-modal-heading"><div><span className="local-eyebrow">{eyebrow}</span><h2>{title}</h2><p>{description}</p></div><button className="local-icon-button" onClick={onClose} aria-label="Close dialog"><X size={18} /></button></div>{children}</section></div>;
}

function PageEngineView({ workspace, query, busy, onGenerate, onPreview, onOpenProfile }: { workspace: LocalWorkspace; query: string; busy: boolean; onGenerate: (serviceIds: string[], locationIds: string[]) => void; onPreview: (pageId: string) => void; onOpenProfile: () => void }) {
  const [serviceId, setServiceId] = useState(workspace.services[0]?.id ?? "");
  const [locationIds, setLocationIds] = useState<string[]>(workspace.locations.slice(0, 3).map(location => location.id));
  const [statusFilter, setStatusFilter] = useState<"All" | LocalPageStatus>("All");
  useEffect(() => { if (!workspace.services.some(service => service.id === serviceId)) setServiceId(workspace.services[0]?.id ?? ""); setLocationIds(current => current.filter(id => workspace.locations.some(location => location.id === id)).length ? current.filter(id => workspace.locations.some(location => location.id === id)) : workspace.locations.slice(0, 3).map(location => location.id)); }, [workspace.services, workspace.locations, serviceId]);
  const selectedService = workspace.services.find(service => service.id === serviceId), firstLocation = workspace.locations.find(location => locationIds.includes(location.id)), preview = pageFor(workspace, selectedService, firstLocation);
  const filtered = workspace.pages.filter(page => statusFilter === "All" || page.status === statusFilter).filter(page => !query || `${page.title} ${page.slug}`.toLowerCase().includes(query.toLowerCase()));
  return <><section className="engine-builder-card"><div className="engine-builder-copy"><span className="local-eyebrow">BUILD FROM YOUR DATA</span><h2>Launch a local page cluster</h2><p>Choose a real service and the places you serve. LocalPilot writes the localized page, prepares Service schema, and keeps it in review until you publish.</p>{workspace.services.length === 0 || workspace.locations.length === 0 ? <div className="engine-setup-callout"><span className="move-icon mint"><Building2 size={16} /></span><span><strong>Add your business inputs first</strong><small>Save at least one service and one location to generate a page.</small></span><button className="text-button" onClick={onOpenProfile}>Open profile <ArrowRight size={14} /></button></div> : <><div className="builder-form-row"><div className="builder-field"><label htmlFor="service-select">Service</label><div className="builder-select"><span className="builder-select-mark"><Zap size={12} /></span><select id="service-select" value={serviceId} onChange={event => setServiceId(event.target.value)}>{workspace.services.map(service => <option value={service.id} key={service.id}>{service.name}</option>)}</select><ChevronDown size={14} /></div></div><div className="builder-field"><label>Locations <span>{locationIds.length} selected</span></label><div className="builder-location-select location-picker">{workspace.locations.map(location => <button type="button" key={location.id} className={locationIds.includes(location.id) ? "selected" : ""} onClick={() => setLocationIds(current => current.includes(location.id) ? current.filter(id => id !== location.id) : [...current, location.id])}>{locationLabel(location)}</button>)}</div></div></div><div className="builder-footer"><span><Check size={14} /> Localized copy <Check size={14} /> Schema graph <Check size={14} /> Conversion events</span><button className="local-button primary" onClick={() => onGenerate(serviceId ? [serviceId] : [], locationIds)} disabled={busy || !serviceId || !locationIds.length}>{busy ? <RefreshCw size={15} className="local-spin" /> : <Sparkles size={15} />}{busy ? "Generating…" : `Generate ${locationIds.length || 0} page${locationIds.length === 1 ? "" : "s"}`}</button></div></>}</div><div className="engine-preview-card">{preview ? <><div className="preview-browser-bar"><span /><span /><span /><small>{preview.slug}</small></div><div className="preview-page"><span className="preview-kicker">{preview.location.toUpperCase()} · {selectedService?.name.toUpperCase()}</span><strong>{preview.title}</strong><span>{preview.intro}</span><div className="preview-buttons"><i>Call now</i><i>WhatsApp</i></div></div><div className="preview-tag"><Code2 size={13} /> Schema graph ready</div></> : <div className="engine-preview-empty"><Globe2 size={24} /><strong>Page preview</strong><span>Select a service and location to see localized copy.</span></div>}</div></section><div className="local-subheader"><div><span className="local-eyebrow">PAGE INVENTORY</span><h2>Landing pages</h2></div><div className="subheader-actions"><span className="inventory-count">{workspace.pages.length} total</span><select className="local-filter-select" value={statusFilter} onChange={event => setStatusFilter(event.target.value as "All" | LocalPageStatus)}><option>All</option><option>Draft</option><option>Needs review</option><option>Live</option></select></div></div><section className="page-table-card">{filtered.length ? <><div className="page-table-head"><span>Page</span><span>Status</span><span>Views</span><span>Leads</span><span>Updated</span><span /></div><div className="page-table-body">{filtered.map((page, index) => <PageRow key={page.id} page={page} workspace={workspace} index={index} onPreview={onPreview} />)}</div></> : <EmptyState title={workspace.pages.length ? "No pages match this filter" : "No landing pages yet"} description={workspace.pages.length ? "Try a different status or search term." : "Generate your first service and location combination above."} />}{workspace.pages.length > 0 && <div className="table-footer"><span>{filtered.length} of {workspace.pages.length} pages</span><span>Draft pages stay private until you publish them.</span></div>}</section></>;
}

function LeadsView({ workspace, query, filter, onFilter, onAdd, onSelect, onExport }: { workspace: LocalWorkspace; query: string; filter: "All" | LocalLeadChannel; onFilter: (filter: "All" | LocalLeadChannel) => void; onAdd: () => void; onSelect: (lead: LocalLead) => void; onExport: () => void }) {
  const filtered = workspace.leads.filter(lead => filter === "All" || lead.channel === filter).filter(lead => !query || `${lead.name} ${lead.email} ${lead.phone} ${workspace.pages.find(page => page.id === lead.pageId)?.title ?? ""}`.toLowerCase().includes(query.toLowerCase()));
  const booked = workspace.leads.filter(lead => lead.status === "Booked").length, newLeads = workspace.leads.filter(lead => lead.status === "New").length, value = workspace.leads.reduce((sum, lead) => sum + (lead.value ?? 0), 0);
  return <><section className="lead-summary-grid"><MetricCard label="Qualified leads" value={String(workspace.leads.length)} change={newLeads ? `${newLeads} new` : undefined} detail="Captured from your pages" icon={Target} tone="peach" /><MetricCard label="Booked jobs" value={String(booked)} detail={workspace.leads.length ? "Update status as work moves" : "No booked jobs yet"} icon={Check} tone="mint" /><MetricCard label="Pipeline value" value={value ? new Intl.NumberFormat("en-US", { style: "currency", currency: workspace.business.currency, maximumFractionDigits: 0 }).format(value) : "—"} detail={value ? "Entered by your team" : "Add value when qualifying"} icon={TrendingUp} tone="violet" /><MetricCard label="Response time" value="—" detail="Add a workflow integration" icon={Clock3} tone="sky" /></section><section className="local-card lead-pipeline-card"><div className="local-card-heading"><div><span className="local-eyebrow">LEAD PIPELINE</span><h2>Recent enquiries</h2></div><div className="lead-header-actions"><div className="lead-filter-tabs">{(["All", "WhatsApp", "Call", "Form"] as const).map(tab => <button key={tab} className={filter === tab ? "active" : ""} onClick={() => onFilter(tab)}>{tab}{tab === "All" && workspace.leads.length > 0 && <span>{workspace.leads.length}</span>}</button>)}</div><button className="local-button primary" onClick={onAdd}><Plus size={14} /> Add lead</button></div></div>{filtered.length ? <><div className="lead-table-head"><span>Contact</span><span>Source</span><span>Status</span><span>Value</span><span /></div><div className="lead-table-body">{filtered.map(lead => <LeadRow key={lead.id} lead={lead} workspace={workspace} onSelect={onSelect} />)}</div><div className="table-footer"><span>{filtered.length} enquiries shown</span><button className="text-button" onClick={onExport}>Export CSV <ArrowRight size={14} /></button></div></> : <EmptyState title={workspace.leads.length ? "No enquiries match this filter" : "Your lead inbox is empty"} description={workspace.leads.length ? "Try another channel or search term." : "Published page forms will appear here. You can also add a lead manually while setting up your workflow."} action={<button className="local-button secondary" onClick={onAdd}><Plus size={14} /> Add a lead</button>} />}</section></>;
}

function ProfileCheck({ label, detail, ok }: { label: string; detail: string; ok: boolean }) { return <div className="profile-check"><span className={`profile-check-icon ${ok ? "" : "warning"}`}>{ok ? <Check size={13} /> : "!"}</span><span><strong>{label}</strong><small>{detail}</small></span>{ok ? <Check size={14} className="profile-check-end" /> : <ChevronRight size={15} />}</div>; }
function LocationRow({ location, onRemove, index }: { location: LocalLocation; onRemove: () => void; index: number }) { return <div className="location-row"><span className={`location-pin ${colorFor(index)}`}><MapPin size={15} /></span><span className="location-copy"><strong>{locationLabel(location)}</strong><small>{[location.address, location.postalCode].filter(Boolean).join(" · ") || "Add a street address for better schema"}</small></span><span className={`location-sync ${location.googleName ? "" : "review"}`}><span />{location.googleName ? "Mapped" : "Ready to map"}</span><button className="local-row-delete" onClick={onRemove} aria-label={`Remove ${locationLabel(location)}`}><Trash2 size={14} /></button></div>; }
function BusinessProfileView({ workspace, syncing, onSaveBusiness, onAddService, onRemoveService, onAddLocation, onRemoveLocation, onSync }: { workspace: LocalWorkspace; syncing: boolean; onSaveBusiness: (business: LocalBusiness) => void; onAddService: (service: Omit<LocalService, "id">) => void; onRemoveService: (id: string) => void; onAddLocation: (location: Omit<LocalLocation, "id" | "googleName">) => void; onRemoveLocation: (id: string) => void; onSync: () => void }) {
  const [business, setBusiness] = useState(workspace.business);
  const [service, setService] = useState({ name: "", description: "" });
  const [location, setLocation] = useState({ city: "", region: "", address: "", postalCode: "", country: "US", details: "" });
  useEffect(() => setBusiness(workspace.business), [workspace.business]);
  const complete = businessCompletion(workspace.business), schema = workspace.business.name ? { "@context": "https://schema.org", "@type": workspace.business.category, name: workspace.business.name, telephone: workspace.business.phone || undefined, url: workspace.business.website || undefined, areaServed: workspace.locations.map(item => locationLabel(item)) } : { "@context": "https://schema.org", "@type": "LocalBusiness", name: "" };
  return <><section className="profile-hero-card"><div className="profile-hero-brand"><span className="profile-logo"><Building2 size={22} /></span><div><span className="local-eyebrow">PROFILE RECORD</span><h2>{workspace.business.name || "Your business"}</h2><p>{workspace.business.category === "LocalBusiness" ? "Choose a business type to improve schema" : workspace.business.category} · {workspace.locations.length} location{workspace.locations.length === 1 ? "" : "s"}</p></div></div><div className="profile-hero-actions"><span className="sync-health"><span className={workspace.business.gbpConnected ? "connected" : ""} />{workspace.business.lastSyncedAt ? `Checked ${relativeTime(workspace.business.lastSyncedAt)}` : "Profile not checked"}</span><button className="local-button primary" onClick={onSync} disabled={syncing || !workspace.business.name}>{syncing ? <RefreshCw size={15} className="local-spin" /> : <RefreshCw size={15} />}{syncing ? "Checking…" : "Run profile check"}</button></div></section><div className="profile-layout"><section className="local-card profile-details-card"><div className="local-card-heading"><div><span className="local-eyebrow">BUSINESS DETAILS</span><h2>{complete}% complete</h2></div><span className="profile-score">{complete === 100 ? "Ready" : "Needs input"}</span></div><div className="profile-progress"><span style={{ width: `${complete}%` }} /></div><form className="profile-form" onSubmit={event => { event.preventDefault(); onSaveBusiness({ ...business, category: business.category as LocalBusiness["category"] }); }}><div className="form-grid"><label>Business name<input value={business.name} onChange={event => setBusiness({ ...business, name: event.target.value })} placeholder="Your business name" /></label><label>Business type<select value={business.category} onChange={event => setBusiness({ ...business, category: event.target.value as LocalBusiness["category"] })}>{BUSINESS_TYPES.map(type => <option key={type} value={type}>{type}</option>)}</select></label><label>Owner or contact<input value={business.ownerName} onChange={event => setBusiness({ ...business, ownerName: event.target.value })} placeholder="Who receives enquiries?" /></label><label>Phone<input value={business.phone} onChange={event => setBusiness({ ...business, phone: event.target.value })} placeholder="+1 555 000 0000" /></label><label>WhatsApp number<input value={business.whatsapp} onChange={event => setBusiness({ ...business, whatsapp: event.target.value })} placeholder="Optional, with country code" /></label><label>Website<input value={business.website} onChange={event => setBusiness({ ...business, website: event.target.value })} placeholder="https://yourdomain.com" /></label><label>Google Business Profile URL<input value={business.gbpUrl} onChange={event => setBusiness({ ...business, gbpUrl: event.target.value })} placeholder="Optional profile URL" /></label><label>Currency<input maxLength={3} value={business.currency} onChange={event => setBusiness({ ...business, currency: event.target.value.toUpperCase() })} placeholder="USD" /></label></div><label className="full-field">Business description<textarea value={business.description} onChange={event => setBusiness({ ...business, description: event.target.value })} placeholder="Describe what makes your business useful to local customers." rows={3} /></label><button className="local-button primary" type="submit"><Check size={14} /> Save business profile</button></form></section><section className="local-card schema-card"><div className="local-card-heading"><div><span className="local-eyebrow">STRUCTURED DATA PREVIEW</span><h2>Schema graph</h2></div><span className="schema-score"><Check size={13} /> {workspace.business.name ? "Ready to inject" : "Waiting for profile"}</span></div><div className="schema-code"><div><span className="code-dot pink" /><span className="code-dot yellow" /><span className="code-dot green" /><small>generated from your saved profile</small></div><pre>{JSON.stringify(schema, null, 2)}</pre></div><div className="schema-footer"><span><span className="schema-check" /> Business</span><span><span className="schema-check" /> Service</span><span><span className="schema-check" /> Page</span><button aria-label="Copy schema" className="local-icon-button" onClick={() => void navigator.clipboard?.writeText(JSON.stringify(schema, null, 2))}><Copy size={15} /></button></div></section></div><div className="profile-layout profile-lists"><section className="local-card location-card"><div className="local-card-heading"><div><span className="local-eyebrow">SERVICE CATALOG</span><h2>What you do</h2></div></div><form className="inline-add-form" onSubmit={event => { event.preventDefault(); if (!service.name.trim() || !service.description.trim()) return; onAddService(service); setService({ name: "", description: "" }); }}><input value={service.name} onChange={event => setService({ ...service, name: event.target.value })} placeholder="Service name" /><input value={service.description} onChange={event => setService({ ...service, description: event.target.value })} placeholder="Short localized description" /><button className="local-button secondary" type="submit"><Plus size={14} /> Add service</button></form><div className="saved-record-list">{workspace.services.length ? workspace.services.map((item, index) => <div className="saved-record" key={item.id}><span className={`page-row-icon ${colorFor(index)}`}><Zap size={14} /></span><span><strong>{item.name}</strong><small>{item.description}</small></span><button className="local-row-delete" onClick={() => onRemoveService(item.id)} aria-label={`Remove ${item.name}`}><Trash2 size={14} /></button></div>) : <p className="record-empty">No services saved yet.</p>}</div></section><section className="local-card location-card"><div className="local-card-heading"><div><span className="local-eyebrow">LOCATION COVERAGE</span><h2>Where you serve</h2></div></div><form className="inline-add-form location-form" onSubmit={event => { event.preventDefault(); if (!location.city.trim()) return; onAddLocation(location); setLocation({ city: "", region: "", address: "", postalCode: "", country: "US", details: "" }); }}><input value={location.city} onChange={event => setLocation({ ...location, city: event.target.value })} placeholder="City" /><input value={location.region} onChange={event => setLocation({ ...location, region: event.target.value })} placeholder="State / region" /><input value={location.address} onChange={event => setLocation({ ...location, address: event.target.value })} placeholder="Street address (optional)" /><button className="local-button secondary" type="submit"><Plus size={14} /> Add location</button></form><div className="location-list">{workspace.locations.length ? workspace.locations.map((item, index) => <LocationRow key={item.id} location={item} index={index} onRemove={() => onRemoveLocation(item.id)} />) : <p className="record-empty">No locations saved yet.</p>}</div></section></div></>;
}

function ContentLibraryView({ workspace, query, onAdd, onEdit, onRemove }: { workspace: LocalWorkspace; query: string; onAdd: () => void; onEdit: (block: LocalContentBlock) => void; onRemove: (id: string) => void }) {
  const blocks = workspace.contentBlocks.filter(block => !query || `${block.title} ${block.body} ${block.author}`.toLowerCase().includes(query.toLowerCase()));
  return <><section className="content-library-hero"><div><span className="local-eyebrow">YOUR COPY SYSTEM</span><h2>Build once. Localize where it matters.</h2><p>Save the proof and answers your team already uses, then include them in generated pages when they are relevant.</p></div><button className="local-button primary" onClick={onAdd}><Plus size={15} /> New content block</button></section>{blocks.length ? <section className="library-grid">{blocks.map((block, index) => <article className="library-card saved-library-card" key={block.id}><span className={`library-icon ${colorFor(index)}`}><FileCode2 size={18} /></span><span className="library-card-copy"><strong>{block.title}</strong><small>{block.type}{block.author ? ` · ${block.author}` : ""}</small><em>{block.body}</em></span><span className="library-card-footer"><button className="text-button" onClick={() => onEdit(block)}>Edit</button><button className="local-row-delete" onClick={() => onRemove(block.id)} aria-label={`Remove ${block.title}`}><Trash2 size={14} /></button></span></article>)}</section> : <section className="local-card"><EmptyState title={workspace.contentBlocks.length ? "No content matches your search" : "Your content library is empty"} description={workspace.contentBlocks.length ? "Try another search term." : "Add a testimonial, FAQ, or location intro to strengthen your generated pages."} action={<button className="local-button secondary" onClick={onAdd}><Plus size={14} /> Add content block</button>} /></section>}</>;
}

function SetupModal({ initial, onClose, onSave }: { initial: LocalBusiness; onClose: () => void; onSave: (business: LocalBusiness) => void }) {
  const [business, setBusiness] = useState(initial); const [error, setError] = useState("");
  return <ModalShell eyebrow="FIRST STEP" title="Set up your business." description="This workspace starts empty. Add the basics, then create your first service and location." onClose={onClose}><form className="profile-form modal-profile-form" onSubmit={event => { event.preventDefault(); if (!business.name.trim()) { setError("Enter your business name to continue."); return; } setError(""); onSave({ ...business, category: business.category as LocalBusiness["category"] }); }}><div className="form-grid"><label>Business name<input autoFocus value={business.name} onChange={event => setBusiness({ ...business, name: event.target.value })} placeholder="Your business name" /></label><label>Business type<select value={business.category} onChange={event => setBusiness({ ...business, category: event.target.value as LocalBusiness["category"] })}>{BUSINESS_TYPES.map(type => <option key={type}>{type}</option>)}</select></label><label>Phone<input value={business.phone} onChange={event => setBusiness({ ...business, phone: event.target.value })} placeholder="+1 555 000 0000" /></label><label>Website<input value={business.website} onChange={event => setBusiness({ ...business, website: event.target.value })} placeholder="https://yourdomain.com" /></label></div>{error && <p className="form-error">{error}</p>}<div className="local-modal-footer"><button className="local-button secondary" type="button" onClick={onClose}>Do this later</button><button className="local-button primary" type="submit"><Check size={15} /> Save and continue</button></div></form></ModalShell>;
}
function LeadModal({ lead, workspace, onClose, onSave, onDelete }: { lead?: LocalLead; workspace: LocalWorkspace; onClose: () => void; onSave: (lead: Omit<LocalLead, "id" | "createdAt"> & { id?: string }) => void; onDelete?: () => void }) {
  const [form, setForm] = useState({ id: lead?.id, pageId: lead?.pageId || workspace.pages[0]?.id || "", name: lead?.name || "", phone: lead?.phone || "", email: lead?.email || "", channel: lead?.channel || "Form" as LocalLeadChannel, status: lead?.status || "New" as LocalLead["status"], notes: lead?.notes || "", value: lead?.value == null ? "" : String(lead.value) });
  const update = (patch: Partial<typeof form>) => setForm(current => ({ ...current, ...patch }));
  return <ModalShell eyebrow={lead ? "LEAD RECORD" : "ADD LEAD"} title={lead ? lead.name : "Capture a new lead."} description="Keep the contact details and source attached to the page that generated the enquiry." onClose={onClose}><form className="profile-form modal-profile-form" onSubmit={event => { event.preventDefault(); const page = workspace.pages.find(item => item.id === form.pageId); onSave({ id: form.id, pageId: page?.id || "", name: form.name, phone: form.phone, email: form.email, channel: form.channel, status: form.status, notes: form.notes, value: form.value ? Number(form.value) : null }); }}><div className="form-grid"><label>Name<input autoFocus value={form.name} onChange={event => update({ name: event.target.value })} placeholder="Contact name" required /></label><label>Page<select value={form.pageId} onChange={event => update({ pageId: event.target.value })}>{workspace.pages.length ? workspace.pages.map(page => <option value={page.id} key={page.id}>{page.title}</option>) : <option value="">No page yet</option>}</select></label><label>Phone<input value={form.phone} onChange={event => update({ phone: event.target.value })} placeholder="Phone number" /></label><label>Email<input type="email" value={form.email} onChange={event => update({ email: event.target.value })} placeholder="Email address" /></label><label>Channel<select value={form.channel} onChange={event => update({ channel: event.target.value as LocalLeadChannel })}><option>Form</option><option>WhatsApp</option><option>Call</option></select></label><label>Estimated value<input type="number" min="0" step="1" value={form.value} onChange={event => update({ value: event.target.value })} placeholder="Optional" /></label></div><label className="full-field">Notes<textarea value={form.notes} onChange={event => update({ notes: event.target.value })} rows={3} placeholder="What does this lead need?" /></label>{lead && <label className="full-field">Status<select value={form.status} onChange={event => update({ status: event.target.value as LocalLead["status"] })}><option>New</option><option>Contacted</option><option>Booked</option></select></label>}<div className="local-modal-footer">{onDelete && <button className="local-button danger" type="button" onClick={onDelete}><Trash2 size={14} /> Delete</button>}<span /><button className="local-button secondary" type="button" onClick={onClose}>Cancel</button><button className="local-button primary" type="submit"><Check size={15} /> Save lead</button></div></form></ModalShell>;
}
function BlockModal({ block, locations, onClose, onSave }: { block?: LocalContentBlock; locations: LocalLocation[]; onClose: () => void; onSave: (block: Omit<LocalContentBlock, "id"> & { id?: string }) => void }) {
  const [form, setForm] = useState({ id: block?.id, title: block?.title || "", type: block?.type || "Testimonial" as LocalContentBlock["type"], body: block?.body || "", author: block?.author || "", locationId: block?.locationId || "" });
  return <ModalShell eyebrow={block ? "CONTENT BLOCK" : "NEW CONTENT BLOCK"} title={block ? "Edit this block." : "Add useful local proof."} description="This content stays in your workspace until you include it on a page." onClose={onClose}><form className="profile-form modal-profile-form" onSubmit={event => { event.preventDefault(); onSave(form); }}><div className="form-grid"><label>Title<input autoFocus value={form.title} onChange={event => setForm({ ...form, title: event.target.value })} placeholder="Example: 24/7 emergency response" required /></label><label>Type<select value={form.type} onChange={event => setForm({ ...form, type: event.target.value as LocalContentBlock["type"] })}><option>Testimonial</option><option>FAQ</option><option>Location intro</option></select></label><label>Author <span className="optional">(for testimonials)</span><input value={form.author} onChange={event => setForm({ ...form, author: event.target.value })} placeholder="Customer or team member" /></label><label>Location <span className="optional">(optional)</span><select value={form.locationId} onChange={event => setForm({ ...form, locationId: event.target.value })}><option value="">All locations</option>{locations.map(location => <option value={location.id} key={location.id}>{locationLabel(location)}</option>)}</select></label></div><label className="full-field">Content<textarea value={form.body} onChange={event => setForm({ ...form, body: event.target.value })} rows={5} placeholder="Write the answer, proof point, or local detail." required /></label><div className="local-modal-footer"><button className="local-button secondary" type="button" onClick={onClose}>Cancel</button><button className="local-button primary" type="submit"><Check size={15} /> Save block</button></div></form></ModalShell>;
}
function PagePreviewModal({ workspace, page, onClose, onPublish, onDelete, onLead, onTrack }: { workspace: LocalWorkspace; page: LocalPage; onClose: () => void; onPublish: () => void; onDelete: () => void; onLead: (lead: Omit<LocalLead, "id" | "createdAt"> & { id?: string }) => void; onTrack: (kind: "call" | "whatsapp") => void }) {
  const [form, setForm] = useState({ name: "", phone: "", email: "", message: "" }); const schema = buildPageSchema(workspace, page, typeof window === "undefined" ? "" : window.location.origin); const live = page.status === "Live";
  return <ModalShell className="preview-modal" eyebrow="PAGE PREVIEW" title={page.title} description="Review the generated copy, schema, and conversion actions before publishing." onClose={onClose}><script type="application/ld+json" dangerouslySetInnerHTML={{ __html: safeSchemaJson(schema) }} /><div className="preview-modal-window"><div className="preview-modal-top"><span className="page-row-icon sky"><Globe2 size={15} /></span><span>/{page.slug}</span><a href={`/local/preview?slug=${encodeURIComponent(page.slug)}`} target="_blank" rel="noreferrer" aria-label="Open public page"><ExternalLink size={14} /></a></div><div className="preview-modal-copy"><span className="preview-kicker">{page.location.toUpperCase()} · {page.title.split("|")[0].trim().toUpperCase()}</span><h3>{page.title}</h3><p>{page.intro}</p><div className="preview-buttons"><a href={workspace.business.phone ? `tel:${workspace.business.phone}` : undefined} onClick={() => { if (live && workspace.business.phone) onTrack("call"); }} className={!workspace.business.phone ? "disabled" : ""}>Call now</a><a href={workspace.business.whatsapp ? `https://wa.me/${workspace.business.whatsapp.replace(/\D/g, "")}` : undefined} target="_blank" rel="noreferrer" onClick={() => { if (live && workspace.business.whatsapp) onTrack("whatsapp"); }} className={!workspace.business.whatsapp ? "disabled" : ""}>WhatsApp</a></div></div></div><section className="preview-lead-form"><div><span className="local-eyebrow">TEST THE CONVERSION FLOW</span><h3>Send an enquiry to this page.</h3><p>This creates a real lead in the workspace so you can verify the pipeline.</p></div><form onSubmit={event => { event.preventDefault(); onLead({ pageId: page.id, name: form.name, phone: form.phone, email: form.email, channel: "Form", status: "New", notes: form.message, value: null }); setForm({ name: "", phone: "", email: "", message: "" }); }}><div className="form-grid"><label>Name<input required value={form.name} onChange={event => setForm({ ...form, name: event.target.value })} placeholder="Your name" /></label><label>Phone or email<input required value={form.phone || form.email} onChange={event => setForm({ ...form, phone: event.target.value, email: "" })} placeholder="How should they reply?" /></label></div><label className="full-field">Message<textarea value={form.message} onChange={event => setForm({ ...form, message: event.target.value })} rows={2} placeholder="What do you need help with?" /></label><button className="local-button secondary" type="submit"><MessageCircle size={14} /> Submit test enquiry</button></form></section><div className="preview-check-row"><span><Check size={14} /> {live ? "Published page" : "Private draft"}</span><span><Check size={14} /> Schema injected</span><span><Check size={14} /> {page.calls + page.whatsappClicks + page.formSubmissions} tracked actions</span></div><div className="local-modal-footer"><button className="local-button danger" onClick={onDelete}><Trash2 size={14} /> Delete page</button><span /><button className="local-button secondary" onClick={onClose}>Close</button>{live ? <a className="local-button primary" href={`/local/preview?slug=${encodeURIComponent(page.slug)}`} target="_blank" rel="noreferrer">Open public page <ExternalLink size={14} /></a> : <button className="local-button primary" onClick={onPublish}><Check size={15} /> Publish page</button>}</div></ModalShell>;
}

export default function LocalDashboard() {
  const [workspace, setWorkspace] = useState<LocalWorkspace | null>(null); const workspaceRef = useRef<LocalWorkspace | null>(null); const [persistence, setPersistence] = useState<LocalPersistence>("loading"); const [view, setView] = useState<View>("Overview"); const [mobileOpen, setMobileOpen] = useState(false); const [dialog, setDialog] = useState<Dialog>(null); const [selectedPageId, setSelectedPageId] = useState<string | null>(null); const [selectedLead, setSelectedLead] = useState<LocalLead | undefined>(); const [query, setQuery] = useState(""); const [leadFilter, setLeadFilter] = useState<"All" | LocalLeadChannel>("All"); const [failure, setFailure] = useState(""); const [toast, setToast] = useState(""); const [generating, setGenerating] = useState(false); const [syncing, setSyncing] = useState(false); const queue = useRef<Promise<unknown>>(Promise.resolve());
  const accept = useCallback((next: LocalWorkspace) => { workspaceRef.current = next; setWorkspace(next); setFailure(""); }, []);
  const refresh = useCallback(async () => { try { const next = await requestLocal(); setPersistence("server"); accept(next); } catch (error) { setPersistence("unavailable"); setFailure(textError(error)); } }, [accept]);
  useEffect(() => { void refresh(); }, [refresh]);
  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(""), 4500); return () => window.clearTimeout(timer); }, [toast]);
  const flash = useCallback((message: string) => setToast(message), []);
  const save = useCallback(async (action: LocalAction, success = "Saved.") => { const pending = queue.current.catch(() => undefined).then(async () => { const next = await requestLocal(action); accept(next); flash(success); return next; }); queue.current = pending; return pending; }, [accept, flash]);
  const navigate = (next: View) => { setView(next); setMobileOpen(false); };
  const openProfile = () => navigate("Business profile");
  const openSetup = () => setDialog({ kind: "setup" });
  const currentPage = workspace?.pages.find(page => page.id === selectedPageId);
  const currentHeading = pageCopy[view];
  const setupNeeded = !!workspace && !workspace.business.name;
  const newLeadCount = workspace?.leads.filter(lead => lead.status === "New").length ?? 0;
  const reviewCount = workspace?.pages.filter(page => page.status === "Needs review").length ?? 0;
  const liveCount = workspace?.pages.filter(page => page.status === "Live").length ?? 0;
  const totalViews = workspace?.pages.reduce((sum, page) => sum + page.visits, 0) ?? 0;
  const totalActions = workspace?.pages.reduce((sum, page) => sum + page.calls + page.whatsappClicks + page.formSubmissions, 0) ?? 0;
  const profilePercent = workspace ? businessCompletion(workspace.business) : 0;
  const bannerTitle = setupNeeded ? "Complete your business profile" : workspace?.pages.length === 0 ? "Your workspace is ready to build" : reviewCount ? `${reviewCount} page${reviewCount === 1 ? " is" : "s are"} waiting for review` : workspace?.business.lastSyncedAt ? "Your local workspace is up to date" : "Run your first profile check";
  const bannerDetail = setupNeeded ? "Add your business name, category, and contact details before generating pages." : workspace?.pages.length === 0 ? "Add a service and location to create your first local landing page." : reviewCount ? "Review copy and publish only the pages you are ready to make public." : workspace?.business.lastSyncedAt ? `Last checked ${relativeTime(workspace.business.lastSyncedAt)}.` : "A profile check records the current connection state in your workspace.";
  const dynamicHeading = view === "Overview" && workspace?.business.name ? { eyebrow: "LOCAL GROWTH WORKSPACE", title: `${workspace.business.name} at a glance.`, description: "Your saved pages, enquiries, and profile readiness in one place." } : currentHeading;

  async function saveBusiness(business: LocalBusiness) { try { await save({ action: "business", business }, "Business profile saved."); setDialog(null); } catch (error) { setFailure(textError(error)); } }
  async function addService(service: Omit<LocalService, "id">) { try { await save({ action: "service", service }, "Service added."); } catch (error) { setFailure(textError(error)); } }
  async function addLocation(location: Omit<LocalLocation, "id" | "googleName">) { try { await save({ action: "location", location }, "Location added."); } catch (error) { setFailure(textError(error)); } }
  async function remove(kind: "service" | "location" | "block" | "page" | "lead", id: string) { try { await save({ action: "remove", kind, id }, "Removed."); } catch (error) { setFailure(textError(error)); } }
  async function generate(serviceIds: string[], locationIds: string[]) { setGenerating(true); try { await save({ action: "generate", serviceIds, locationIds }, "Landing pages generated and saved as drafts."); navigate("Page engine"); } catch (error) { setFailure(textError(error)); } finally { setGenerating(false); } }
  async function savePage(page: LocalPage, status: LocalPageStatus) { try { await save({ action: "page", id: page.id, title: page.title, intro: page.intro, body: page.body, status }, status === "Live" ? "Page published." : "Page updated."); } catch (error) { setFailure(textError(error)); } }
  async function saveLead(lead: Omit<LocalLead, "id" | "createdAt"> & { id?: string }) { try { await save({ action: "lead", lead }, "Lead saved."); setDialog(null); setSelectedLead(undefined); } catch (error) { setFailure(textError(error)); } }
  async function syncProfile() { if (!workspace?.business.name) { openProfile(); flash("Save your business profile before checking it."); return; } setSyncing(true); try { await save({ action: "profile-check", connect: !!workspace.business.gbpUrl } as LocalAction, workspace.business.gbpUrl ? "Profile connection state saved." : "Profile check saved. Add a GBP URL when you are ready to connect it."); } catch (error) { setFailure(textError(error)); } finally { setSyncing(false); } }
  async function track(pageId: string, kind: "call" | "whatsapp") { try { const response = await fetch("/api/local/activity", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ pageId, kind, eventId: randomLocalId("event") }) }); if (!response.ok) throw new Error(); await refresh(); } catch { /* A contact click should never block the caller's link. */ } }
  function exportLeads() { if (!workspace) return; const rows: (string | number)[][] = [["Name", "Phone", "Email", "Page", "Channel", "Status", "Value", "Created"]]; workspace.leads.forEach(lead => rows.push([lead.name, lead.phone, lead.email, workspace.pages.find(page => page.id === lead.pageId)?.title ?? lead.pageId, lead.channel, lead.status, lead.value ?? "", lead.createdAt])); downloadFile(`localpilot-leads-${dateInZone()}.csv`, csvText(rows), "text/csv;charset=utf-8"); flash("Lead CSV downloaded."); }
  if (!workspace) return <div className="local-app"><main className="local-main"><section className="local-card local-loading"><RefreshCw size={22} className="local-spin" /><strong>{persistence === "unavailable" ? "Workspace unavailable" : "Loading your workspace…"}</strong><p>{failure || "Reading your saved LocalPilot records."}</p>{failure && <button className="local-button primary" onClick={() => void refresh()}>Retry</button>}</section></main></div>;

  return <div className="local-app">{mobileOpen && <button className="local-mobile-backdrop" aria-label="Close navigation" onClick={() => setMobileOpen(false)} />}<aside className={`local-sidebar ${mobileOpen ? "open" : ""}`}><div className="local-brand"><span className="local-brand-mark"><span /></span><span>local<span className="local-brand-accent">pilot</span><b>.</b></span></div><button className="local-workspace-picker" onClick={openProfile}><span className="workspace-avatar">{initials(workspace.business.name || "LocalPilot")}</span><span><strong>{workspace.business.name || "New workspace"}</strong><small>{workspace.business.category === "LocalBusiness" ? "Local service workspace" : workspace.business.category}</small></span><ChevronDown size={15} /></button><div className="local-nav-label">WORKSPACE</div><nav className="local-nav" aria-label="LocalPilot navigation">{navigation.map(({ label, icon: Icon }) => <button key={label} className={view === label ? "active" : ""} onClick={() => navigate(label)} aria-current={view === label ? "page" : undefined}><Icon size={17} /><span>{label}</span>{label === "Page engine" && reviewCount > 0 && <em>{reviewCount}</em>}{label === "Leads" && newLeadCount > 0 && <em>{newLeadCount}</em>}</button>)}</nav><div className="local-nav-label locations-label">LOCATIONS <button className="local-sidebar-plus" aria-label="Add location" onClick={openProfile}><Plus size={13} /></button></div><div className="local-location-list">{workspace.locations.length ? workspace.locations.slice(0, 4).map((location, index) => <button className="local-location" key={location.id} onClick={openProfile}><span className={`location-mini ${colorFor(index)}`}><MapPin size={13} /></span><span><strong>{locationLabel(location)}</strong><small>{location.address || "Address not added"}</small></span><span className={`local-live-dot ${location.googleName ? "" : "muted"}`} /></button>) : <button className="local-location empty-location" onClick={openProfile}><span className="location-mini"><MapPin size={13} /></span><span><strong>No locations yet</strong><small>Add where you serve</small></span></button>}<button className="view-locations" onClick={openProfile}>{workspace.locations.length > 4 ? "View all locations" : "Manage locations"} <ArrowRight size={13} /></button></div><div className="local-sidebar-bottom"><button className="local-help-card" onClick={() => flash("Start with your business profile, then add a service and location.")}><span className="help-spark"><Sparkles size={14} /></span><span><strong>Build your local system</strong><small>Open the setup guide</small></span><ArrowUpRight size={14} /></button><a className="old-workspace-link" href="/seo"><LayoutDashboard size={14} /><span>Open SEO Command Center</span><ArrowUpRight size={13} /></a><button className="local-settings" onClick={openProfile}><Settings2 size={15} /><span>Workspace settings</span></button><div className="local-user"><span className="local-user-avatar">{initials(workspace.business.ownerName || workspace.business.name || "You")}</span><span><strong>{workspace.business.ownerName || "Workspace owner"}</strong><small>{persistence === "server" ? "Saved to local server" : "Storage unavailable"}</small></span><MoreHorizontal size={15} /></div></div></aside><main className="local-main"><header className="local-topbar"><div className="local-topbar-left"><button className="local-mobile-menu" aria-label="Open navigation" onClick={() => setMobileOpen(true)}><Menu size={20} /></button><div className="local-breadcrumb"><span>Workspace</span><ChevronRight size={13} /><strong>{view}</strong></div></div><div className="local-top-actions"><label className="local-search"><Search size={16} /><input aria-label="Search workspace" value={query} onChange={event => setQuery(event.target.value)} placeholder="Search saved records" /><kbd>⌘ K</kbd></label><button className="local-top-icon" aria-label="Setup guide" onClick={openProfile}><CircleHelp size={18} /></button><button className="local-top-icon local-notification" aria-label="Open new leads" onClick={() => navigate("Leads")}><Bell size={18} />{newLeadCount > 0 && <span />}</button><span className="top-user-avatar">{initials(workspace.business.ownerName || workspace.business.name || "You")}</span></div></header><div className="local-content"><section className="local-page-heading"><div><span className="local-eyebrow">{dynamicHeading.eyebrow}</span><h1>{dynamicHeading.title}</h1><p>{dynamicHeading.description}</p></div><div className="local-page-actions">{view === "Overview" && <><button className="local-button secondary" onClick={() => workspace.pages.find(page => page.status === "Live") ? setSelectedPageId(workspace.pages.find(page => page.status === "Live")!.id) : navigate("Page engine")}><ExternalLink size={15} /> Preview a page</button><button className="local-button primary" onClick={() => workspace.services.length && workspace.locations.length ? navigate("Page engine") : openProfile()}><Sparkles size={15} /> {workspace.services.length && workspace.locations.length ? "Build pages" : "Set up profile"}</button></>}{view === "Page engine" && <button className="local-button primary" onClick={() => workspace.services.length && workspace.locations.length ? navigate("Page engine") : openProfile()}><Sparkles size={15} /> Generate pages</button>}{view === "Leads" && <button className="local-button secondary" onClick={exportLeads}><ArrowDownRight size={15} /> Export leads</button>}{view === "Business profile" && <button className="local-button secondary" onClick={syncProfile} disabled={syncing}><RefreshCw size={15} /> Check profile</button>}{view === "Content library" && <button className="local-button primary" onClick={() => setDialog({ kind: "block" })}><Plus size={15} /> Add block</button>}</div></section><div className={`local-system-banner ${setupNeeded ? "needs-setup" : ""}`}><span className="system-pulse" /><span><strong>{bannerTitle}</strong><small>{bannerDetail}</small></span><span className="banner-divider" /><span className="banner-detail"><RefreshCw size={14} />{workspace.business.lastSyncedAt ? "Profile check saved" : "No profile check yet"}</span><button onClick={setupNeeded ? openProfile : view === "Page engine" ? () => navigate("Page engine") : openProfile}>{setupNeeded ? "Open profile" : "View status"} <ArrowRight size={14} /></button></div>{failure && <div className="local-system-banner error-banner"><span className="system-pulse" /><span><strong>Could not save that change</strong><small>{failure}</small></span><button onClick={() => { setFailure(""); void refresh(); }}>Retry <RefreshCw size={13} /></button></div>}{view === "Overview" && <><section className="local-metrics-grid"><MetricCard label="Live pages" value={String(liveCount)} change={workspace.pages.length ? `${workspace.pages.length} total` : undefined} detail={workspace.pages.length ? "Publish from page engine" : "Generate your first page"} icon={Globe2} tone="sky" /><MetricCard label="Tracked views" value={totalViews ? String(totalViews) : "—"} detail={totalViews ? "From published page links" : "No traffic recorded yet"} icon={Activity} tone="mint" /><MetricCard label="Qualified leads" value={workspace.leads.length ? String(workspace.leads.length) : "—"} change={newLeadCount ? `${newLeadCount} new` : undefined} detail={workspace.leads.length ? "Saved in your lead inbox" : "Publish a form to capture leads"} icon={Target} tone="peach" /><MetricCard label="Profile readiness" value={workspace.business.name ? `${profilePercent}%` : "—"} detail={workspace.business.name ? "Based on saved fields" : "Add business details"} icon={RefreshCw} tone="violet" /></section><section className="local-overview-grid"><article className="local-card visibility-card"><div className="local-card-heading"><div><span className="local-eyebrow">LOCAL PAGE COVERAGE</span><h2>{workspace.pages.length ? "See where your pages exist." : "Your local footprint starts here."}</h2></div><div className="chart-heading-meta"><strong>{workspace.pages.length}<small> pages</small></strong>{workspace.locations.length > 0 && <span><MapPin size={13} /> {workspace.locations.length} location{workspace.locations.length === 1 ? "" : "s"}</span>}</div></div><div className="chart-legend"><span><i className="legend-line" /> Generated pages</span><span><i className="legend-dot" /> Live data only</span></div><CoverageChart workspace={workspace} /></article><article className="local-card next-moves-card"><div className="local-card-heading"><div><span className="local-eyebrow">NEXT STEPS</span><h2>Make the next useful move.</h2></div></div><div className="move-list">{setupNeeded && <button className="move-item" onClick={openProfile}><span className="move-icon peach"><Building2 size={16} /></span><span><strong>Complete your business profile</strong><small>Name, category, contact, and website</small></span><ArrowRight size={15} /></button>}{workspace.services.length === 0 && <button className="move-item" onClick={openProfile}><span className="move-icon violet"><Zap size={16} /></span><span><strong>Add your first service</strong><small>Describe what customers can hire you for</small></span><ArrowRight size={15} /></button>}{workspace.locations.length === 0 && <button className="move-item" onClick={openProfile}><span className="move-icon mint"><MapPin size={16} /></span><span><strong>Add a service location</strong><small>Pages need a real place to target</small></span><ArrowRight size={15} /></button>}{workspace.services.length > 0 && workspace.locations.length > 0 && workspace.pages.length === 0 && <button className="move-item" onClick={() => navigate("Page engine")}><span className="move-icon peach"><Sparkles size={16} /></span><span><strong>Generate your first page</strong><small>Start with one service and one place</small></span><ArrowRight size={15} /></button>}{newLeadCount > 0 && <button className="move-item" onClick={() => navigate("Leads")}><span className="move-icon mint"><Phone size={16} /></span><span><strong>Follow up with {newLeadCount} new lead{newLeadCount === 1 ? "" : "s"}</strong><small>Keep response work inside the inbox</small></span><ArrowRight size={15} /></button>}{!setupNeeded && workspace.services.length > 0 && workspace.locations.length > 0 && workspace.pages.length > 0 && !newLeadCount && <button className="move-item" onClick={() => setDialog({ kind: "block" })}><span className="move-icon violet"><BookOpen size={16} /></span><span><strong>Add local proof to your pages</strong><small>Testimonials and FAQs improve usefulness</small></span><ArrowRight size={15} /></button>}</div></article></section><section className="local-bottom-grid"><article className="local-card page-engine-card"><div className="local-card-heading"><div><span className="local-eyebrow">PAGE ENGINE</span><h2>Pages from your saved inputs.</h2><p>{workspace.pages.length ? `${liveCount} live · ${reviewCount} waiting for review` : "No page records have been generated yet."}</p></div><button className="text-button" onClick={() => navigate("Page engine")}>Open engine <ArrowRight size={14} /></button></div>{workspace.pages.length ? <><div className="page-table-head overview-table-head"><span>Page</span><span>Status</span><span>Views</span><span>Leads</span><span /></div><div className="page-table-body">{workspace.pages.slice(0, 3).map((page, index) => <PageRow key={page.id} page={page} workspace={workspace} index={index} onPreview={setSelectedPageId} />)}</div><div className="table-footer"><span>{workspace.pages.length} saved page{workspace.pages.length === 1 ? "" : "s"}</span><button className="text-button" onClick={() => navigate("Page engine")}>Manage pages <ArrowRight size={14} /></button></div></> : <EmptyState title="No landing pages yet" description="Generate a page cluster after adding a service and location." action={<button className="local-button primary" onClick={workspace.services.length && workspace.locations.length ? () => navigate("Page engine") : openProfile}><Plus size={14} /> {workspace.services.length && workspace.locations.length ? "Generate pages" : "Set up inputs"}</button>} />}</article><article className="local-card recent-leads-card"><div className="local-card-heading"><div><span className="local-eyebrow">LEAD ACTIVITY</span><h2>{workspace.leads.length ? "Recent enquiries." : "Your lead inbox."}</h2></div><button className="text-button" onClick={() => navigate("Leads")}>View all <ArrowRight size={14} /></button></div>{workspace.leads.length ? <div className="mini-lead-list">{workspace.leads.slice(0, 3).map(lead => <LeadRow key={lead.id} lead={lead} onSelect={item => { setSelectedLead(item); setDialog({ kind: "lead", lead: item }); }} />)}</div> : <EmptyState title="No leads yet" description="Publish a page and its form enquiries will land here." action={<button className="local-button secondary" onClick={() => setDialog({ kind: "lead" })}><Plus size={14} /> Add a lead</button>} />}</article></section></>}{view === "Page engine" && <PageEngineView workspace={workspace} query={query} busy={generating} onGenerate={generate} onPreview={setSelectedPageId} onOpenProfile={openProfile} />}{view === "Leads" && <LeadsView workspace={workspace} query={query} filter={leadFilter} onFilter={setLeadFilter} onAdd={() => { setSelectedLead(undefined); setDialog({ kind: "lead" }); }} onSelect={lead => { setSelectedLead(lead); setDialog({ kind: "lead", lead }); }} onExport={exportLeads} />}{view === "Business profile" && <BusinessProfileView workspace={workspace} syncing={syncing} onSaveBusiness={saveBusiness} onAddService={addService} onRemoveService={id => void remove("service", id)} onAddLocation={addLocation} onRemoveLocation={id => void remove("location", id)} onSync={syncProfile} />}{view === "Content library" && <ContentLibraryView workspace={workspace} query={query} onAdd={() => setDialog({ kind: "block" })} onEdit={block => setDialog({ kind: "block", block })} onRemove={id => void remove("block", id)} />}<footer className="local-footer"><span><span className="footer-health-dot" /> {persistence === "server" ? "Saved to your LocalPilot workspace" : "Storage unavailable"}</span><span>{workspace.updatedAt ? `Updated ${displayUpdated(workspace.updatedAt)}` : "Not saved yet"}</span></footer></div></main>{dialog?.kind === "setup" && <SetupModal initial={workspace.business} onClose={() => setDialog(null)} onSave={saveBusiness} />}{dialog?.kind === "lead" && <LeadModal lead={dialog.lead} workspace={workspace} onClose={() => { setDialog(null); setSelectedLead(undefined); }} onSave={saveLead} onDelete={dialog.lead ? () => { void remove("lead", dialog.lead!.id); setDialog(null); setSelectedLead(undefined); } : undefined} />}{dialog?.kind === "block" && <BlockModal block={dialog.block} locations={workspace.locations} onClose={() => setDialog(null)} onSave={async block => { try { await save({ action: "block", block }, "Content block saved."); setDialog(null); } catch (error) { setFailure(textError(error)); } }} />}{currentPage && <PagePreviewModal workspace={workspace} page={currentPage} onClose={() => setSelectedPageId(null)} onPublish={() => void savePage(currentPage, "Live")} onDelete={() => { void remove("page", currentPage.id); setSelectedPageId(null); }} onLead={lead => void saveLead(lead)} onTrack={kind => void track(currentPage.id, kind)} />}{toast && <div className="local-toast" role="status"><span><Check size={15} /></span>{toast}<button aria-label="Dismiss notification" onClick={() => setToast("")}><X size={14} /></button></div>}</div>;
}
